  public static func createCLGRecordRef(
    _ fbb: inout FlatBufferBuilder,
    STANDARDOffset STANDARD: Offset,
    RECORD_IDOffset RECORD_ID: Offset,
    SHA256Offset SHA256: Offset,
    URIOffset URI: Offset = Offset()
  ) -> Offset {
    let __start = CLGRecordRef.startCLGRecordRef(&fbb)
    CLGRecordRef.add(STANDARD: STANDARD, &fbb)
    CLGRecordRef.add(RECORD_ID: RECORD_ID, &fbb)
    CLGRecordRef.add(SHA256: SHA256, &fbb)
    CLGRecordRef.add(URI: URI, &fbb)
    return CLGRecordRef.endCLGRecordRef(&fbb, start: __start)
  }

