  public static func createCLGSource(
    _ fbb: inout FlatBufferBuilder,
    CATEGORY: clgSourceCategory = .unspecified,
    RECORDOffset RECORD: Offset,
    THEORYOffset THEORY: Offset,
    PROVIDER_IDOffset PROVIDER_ID: Offset = Offset(),
    PROVIDER_VERSIONOffset PROVIDER_VERSION: Offset = Offset(),
    PROVIDER_SHA256Offset PROVIDER_SHA256: Offset = Offset(),
    CONFIGURATIONOffset CONFIGURATION: Offset = Offset(),
    ATTITUDEOffset ATTITUDE: Offset = Offset(),
    AUXILIARYVectorOffset AUXILIARY: Offset = Offset(),
    INTERPOLATION_IDOffset INTERPOLATION_ID: Offset,
    POSITION_ERROR_M: Double = .nan,
    VELOCITY_ERROR_MPS: Double = .nan,
    ACCELERATION_ERROR_MPS2: Double = .nan,
    JERK_ERROR_MPS3: Double = .nan,
    ATTITUDE_ERROR_RAD: Double = .nan,
    ANGULAR_RATE_ERROR_RAD_S: Double = .nan,
    ANGULAR_ACCELERATION_ERROR_RAD_S2: Double = .nan,
    HAS_CATEGORY: Bool = false,
    HAS_POSITION_ERROR_M: Bool = false,
    HAS_VELOCITY_ERROR_MPS: Bool = false,
    HAS_ACCELERATION_ERROR_MPS2: Bool = false,
    HAS_JERK_ERROR_MPS3: Bool = false,
    HAS_ATTITUDE_ERROR_RAD: Bool = false,
    HAS_ANGULAR_RATE_ERROR_RAD_S: Bool = false,
    HAS_ANGULAR_ACCELERATION_ERROR_RAD_S2: Bool = false
  ) -> Offset {
    let __start = CLGSource.startCLGSource(&fbb)
    CLGSource.add(CATEGORY: CATEGORY, &fbb)
    CLGSource.add(RECORD: RECORD, &fbb)
    CLGSource.add(THEORY: THEORY, &fbb)
    CLGSource.add(PROVIDER_ID: PROVIDER_ID, &fbb)
    CLGSource.add(PROVIDER_VERSION: PROVIDER_VERSION, &fbb)
    CLGSource.add(PROVIDER_SHA256: PROVIDER_SHA256, &fbb)
    CLGSource.add(CONFIGURATION: CONFIGURATION, &fbb)
    CLGSource.add(ATTITUDE: ATTITUDE, &fbb)
    CLGSource.addVectorOf(AUXILIARY: AUXILIARY, &fbb)
    CLGSource.add(INTERPOLATION_ID: INTERPOLATION_ID, &fbb)
    CLGSource.add(POSITION_ERROR_M: POSITION_ERROR_M, &fbb)
    CLGSource.add(VELOCITY_ERROR_MPS: VELOCITY_ERROR_MPS, &fbb)
    CLGSource.add(ACCELERATION_ERROR_MPS2: ACCELERATION_ERROR_MPS2, &fbb)
    CLGSource.add(JERK_ERROR_MPS3: JERK_ERROR_MPS3, &fbb)
    CLGSource.add(ATTITUDE_ERROR_RAD: ATTITUDE_ERROR_RAD, &fbb)
    CLGSource.add(ANGULAR_RATE_ERROR_RAD_S: ANGULAR_RATE_ERROR_RAD_S, &fbb)
    CLGSource.add(ANGULAR_ACCELERATION_ERROR_RAD_S2: ANGULAR_ACCELERATION_ERROR_RAD_S2, &fbb)
    CLGSource.add(HAS_CATEGORY: HAS_CATEGORY, &fbb)
    CLGSource.add(HAS_POSITION_ERROR_M: HAS_POSITION_ERROR_M, &fbb)
    CLGSource.add(HAS_VELOCITY_ERROR_MPS: HAS_VELOCITY_ERROR_MPS, &fbb)
    CLGSource.add(HAS_ACCELERATION_ERROR_MPS2: HAS_ACCELERATION_ERROR_MPS2, &fbb)
    CLGSource.add(HAS_JERK_ERROR_MPS3: HAS_JERK_ERROR_MPS3, &fbb)
    CLGSource.add(HAS_ATTITUDE_ERROR_RAD: HAS_ATTITUDE_ERROR_RAD, &fbb)
    CLGSource.add(HAS_ANGULAR_RATE_ERROR_RAD_S: HAS_ANGULAR_RATE_ERROR_RAD_S, &fbb)
    CLGSource.add(HAS_ANGULAR_ACCELERATION_ERROR_RAD_S2: HAS_ANGULAR_ACCELERATION_ERROR_RAD_S2, &fbb)
    return CLGSource.endCLGSource(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.CATEGORY, fieldName: "CATEGORY", required: false, type: clgSourceCategory.self)
    try _v.visit(field: VT.RECORD, fieldName: "RECORD", required: true, type: ForwardOffset<CLGRecordRef>.self)
    try _v.visit(field: VT.THEORY, fieldName: "THEORY", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROVIDER_ID, fieldName: "PROVIDER_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROVIDER_VERSION, fieldName: "PROVIDER_VERSION", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROVIDER_SHA256, fieldName: "PROVIDER_SHA256", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CONFIGURATION, fieldName: "CONFIGURATION", required: false, type: ForwardOffset<CLGRecordRef>.self)
    try _v.visit(field: VT.ATTITUDE, fieldName: "ATTITUDE", required: false, type: ForwardOffset<CLGRecordRef>.self)
    try _v.visit(field: VT.AUXILIARY, fieldName: "AUXILIARY", required: false, type: ForwardOffset<Vector<ForwardOffset<CLGRecordRef>, CLGRecordRef>>.self)
    try _v.visit(field: VT.INTERPOLATION_ID, fieldName: "INTERPOLATION_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.POSITION_ERROR_M, fieldName: "POSITION_ERROR_M", required: false, type: Double.self)
    try _v.visit(field: VT.VELOCITY_ERROR_MPS, fieldName: "VELOCITY_ERROR_MPS", required: false, type: Double.self)
    try _v.visit(field: VT.ACCELERATION_ERROR_MPS2, fieldName: "ACCELERATION_ERROR_MPS2", required: false, type: Double.self)
    try _v.visit(field: VT.JERK_ERROR_MPS3, fieldName: "JERK_ERROR_MPS3", required: false, type: Double.self)
    try _v.visit(field: VT.ATTITUDE_ERROR_RAD, fieldName: "ATTITUDE_ERROR_RAD", required: false, type: Double.self)
    try _v.visit(field: VT.ANGULAR_RATE_ERROR_RAD_S, fieldName: "ANGULAR_RATE_ERROR_RAD_S", required: false, type: Double.self)
    try _v.visit(field: VT.ANGULAR_ACCELERATION_ERROR_RAD_S2, fieldName: "ANGULAR_ACCELERATION_ERROR_RAD_S2", required: false, type: Double.self)
    try _v.visit(field: VT.HAS_CATEGORY, fieldName: "HAS_CATEGORY", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_POSITION_ERROR_M, fieldName: "HAS_POSITION_ERROR_M", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_VELOCITY_ERROR_MPS, fieldName: "HAS_VELOCITY_ERROR_MPS", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_ACCELERATION_ERROR_MPS2, fieldName: "HAS_ACCELERATION_ERROR_MPS2", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_JERK_ERROR_MPS3, fieldName: "HAS_JERK_ERROR_MPS3", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_ATTITUDE_ERROR_RAD, fieldName: "HAS_ATTITUDE_ERROR_RAD", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_ANGULAR_RATE_ERROR_RAD_S, fieldName: "HAS_ANGULAR_RATE_ERROR_RAD_S", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_ANGULAR_ACCELERATION_ERROR_RAD_S2, fieldName: "HAS_ANGULAR_ACCELERATION_ERROR_RAD_S2", required: false, type: Bool.self)
    _v.finish()
  }
}

