  ///  Presence flag required; finite >=0, added to EACH semiaxis only when BOTH
  ///  endpoints are SPACECRAFT. BodyDescriptor always describes true surface.
  public var SPACE_SPACE_SKIM_MARGIN_M: Double { let o = _accessor.offset(VT.SPACE_SPACE_SKIM_MARGIN_M); return o == 0 ? .nan : _accessor.readBuffer(of: Double.self, at: o) }
