   at: VT.FRAME_STATIONARY) }
  public static func add(CLEARANCE: clgClearanceMode, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CLEARANCE.rawValue, def: 0, at: VT.CLEARANCE) }
  public static func add(SPACE_SPACE_SKIM_MARGIN_M: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: SPACE_SPACE_SKIM_MARGIN_M, def: .nan, at: VT.SPACE_SPACE_SKIM_MARGIN_M) }
