   at: VT.HAS_FRAME_STATIONARY) }
  public static func add(HAS_CLEARANCE: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: HAS_CLEARANCE, def: false,
   at: VT.HAS_CLEARANCE) }
  public static func add(HAS_SPACE_SPACE_SKIM_MARGIN_M: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: HAS_SPACE_SPACE_SKIM_MARGIN_M, def: false,
   at: VT.HAS_SPACE_SPACE_SKIM_MARGIN_M) }
  public static func endCLGBody(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [4]); return end }
  public static func createCLGBody(
    _ fbb: inout FlatBufferBuilder,
    MODELOffset MODEL: Offset,
    MOTION_SOURCE_INDEX: Int32 = -1,
    FRAME_STATIONARY: Bool = false,
    CLEARANCE: clgClearanceMode = .unspecified,
    SPACE_SPACE_SKIM_MARGIN_M: Double = .nan,
    HAS_MOTION_SOURCE_INDEX: Bool = false,
    HAS_FRAME_STATIONARY: Bool = false,
    HAS_CLEARANCE: Bool = false,
    HAS_SPACE_SPACE_SKIM_MARGIN_M: Bool = false
  ) -> Offset {
    let __start = CLGBody.startCLGBody(&fbb)
    CLGBody.add(MODEL: MODEL, &fbb)
    CLGBody.add(MOTION_SOURCE_INDEX: MOTION_SOURCE_INDEX, &fbb)
    CLGBody.add(FRAME_STATIONARY: FRAME_STATIONARY, &fbb)
    CLGBody.add(CLEARANCE: CLEARANCE, &fbb)
    CLGBody.add(SPACE_SPACE_SKIM_MARGIN_M: SPACE_SPACE_SKIM_MARGIN_M, &fbb)
    CLGBody.add(HAS_MOTION_SOURCE_INDEX: HAS_MOTION_SOURCE_INDEX, &fbb)
    CLGBody.add(HAS_FRAME_STATIONARY: HAS_FRAME_STATIONARY, &fbb)
    CLGBody.add(HAS_CLEARANCE: HAS_CLEARANCE, &fbb)
    CLGBody.add(HAS_SPACE_SPACE_SKIM_MARGIN_M: HAS_SPACE_SPACE_SKIM_MARGIN_M, &fbb)
    return CLGBody.endCLGBody(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.MODEL, fieldName: "MODEL", required: true, type: ForwardOffset<BodyDescriptor>.self)
    try _v.visit(field: VT.MOTION_SOURCE_INDEX, fieldName: "MOTION_SOURCE_INDEX", required: false, type: Int32.self)
    try _v.visit(field: VT.FRAME_STATIONARY, fieldName: "FRAME_STATIONARY", required: false, type: Bool.self)
    try _v.visit(field: VT.CLEARANCE, fieldName: "CLEARANCE", required: false, type: clgClearanceMode.self)
    try _v.visit(field: VT.SPACE_SPACE_SKIM_MARGIN_M, fieldName: "SPACE_SPACE_SKIM_MARGIN_M", required: false, type: Double.self)
    try _v.visit(field: VT.HAS_MOTION_SOURCE_INDEX, fieldName: "HAS_MOTION_SOURCE_INDEX", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_FRAME_STATIONARY, fieldName: "HAS_FRAME_STATIONARY", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_CLEARANCE, fieldName: "HAS_CLEARANCE", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_SPACE_SPACE_SKIM_MARGIN_M, fieldName: "HAS_SPACE_SPACE_SKIM_MARGIN_M", required: false, type: Bool.self)
    _v.finish()
  }
