  ///  Longer analyses split/re-epoch definitions; never use year-long doubles.
  public var START_OFFSET_S: Double { let o = _accessor.offset(VT.START_OFFSET_S); return o == 0 ? .nan : _accessor.readBuffer(of: Double.self, at: o) }
  public var STOP_OFFSET_S: Double { let o = _accessor.offset(VT.STOP_OFFSET_S); return o == 0 ? .nan : _accessor.readBuffer(of: Double.self, at: o) }
