    CLGBoundary.add(PAIR_INDEX: PAIR_INDEX, &fbb)
    CLGBoundary.add(OFFSET_S: OFFSET_S, &fbb)
    CLGBoundary.add(BRACKET_LO_S: BRACKET_LO_S, &fbb)
    CLGBoundary.add(BRACKET_HI_S: BRACKET_HI_S, &fbb)
    CLGBoundary.addVectorOf(CAUSES: CAUSES, &fbb)
    CLGBoundary.addVectorOf(RAY_TIMES: RAY_TIMES, &fbb)
    CLGBoundary.add(HAS_OFFSET_S: HAS_OFFSET_S, &fbb)
    CLGBoundary.add(HAS_BRACKET_LO_S: HAS_BRACKET_LO_S, &fbb)
    CLGBoundary.add(HAS_BRACKET_HI_S: HAS_BRACKET_HI_S, &fbb)
