    try _v.visit(field: VT.OFFSET_S, fieldName: "OFFSET_S", required: false, type: Double.self)
    try _v.visit(field: VT.BRACKET_LO_S, fieldName: "BRACKET_LO_S", required: false, type: Double.self)
    try _v.visit(field: VT.BRACKET_HI_S, fieldName: "BRACKET_HI_S", required: false, type: Double.self)
    try _v.visit(field: VT.CAUSES, fieldName: "CAUSES", required: true, type: ForwardOffset<Vector<CLGCause, CLGCause>>.self)
    try _v.visit(field: VT.RAY_TIMES, fieldName: "RAY_TIMES", required: true, type: ForwardOffset<Vector<CLGRayTimes, CLGRayTimes>>.self)
    try _v.visit(field: VT.HAS_OFFSET_S, fieldName: "HAS_OFFSET_S", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_BRACKET_LO_S, fieldName: "HAS_BRACKET_LO_S", required: false, type: Bool.self)
    try _v.visit(field: VT.HAS_BRACKET_HI_S, fieldName: "HAS_BRACKET_HI_S", required: false, type: Bool.self)
