  public static func createCLGAdjacency(
    _ fbb: inout FlatBufferBuilder,
    EPOCH_S: Double = .nan,
    ORIGIN: clgSnapshotOrigin = .unspecified,
    ROW_OFFSETSVectorOffset ROW_OFFSETS: Offset,
    NEIGHBOR_NODE_INDEXESVectorOffset NEIGHBOR_NODE_INDEXES: Offset,
    LINK_INDEXESVectorOffset LINK_INDEXES: Offset,
    RANGES_MVectorOffset RANGES_M: Offset,
    LIGHT_TIMES_SVectorOffset LIGHT_TIMES_S: Offset,
    RECEPTION_EPOCHS_SVectorOffset RECEPTION_EPOCHS_S: Offset,
    HAS_EPOCH_S: Bool = false,
