    try _v.visit(field: VT.ORIGIN, fieldName: "ORIGIN", required: false, type: clgSnapshotOrigin.self)
    try _v.visit(field: VT.ROW_OFFSETS, fieldName: "ROW_OFFSETS", required: true, type: ForwardOffset<Vector<UInt32, UInt32>>.self)
    try _v.visit(field: VT.NEIGHBOR_NODE_INDEXES, fieldName: "NEIGHBOR_NODE_INDEXES", required: true, type: ForwardOffset<Vector<UInt32, UInt32>>.self)
    try _v.visit(field: VT.LINK_INDEXES, fieldName: "LINK_INDEXES", required: true, type: ForwardOffset<Vector<UInt32, UInt32>>.self)
