///  Exactly one payload; every frame uses the same GRAPH_ID. COMPLETE requires
///  all chunks, definition, implemented scope/enums and host-stamped producer.
public struct CLG: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$CLG" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: CLG.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let GRAPH_ID: VOffset = 4
    static let PAYLOAD: VOffset = 6
    static let DEFINITION: VOffset = 8
    static let STATE_BLOCK: VOffset = 10
    static let RESULT: VOffset = 12
    static let HAS_PAYLOAD: VOffset = 14
  }

  ///  Globally unique across exchanging producers/stores; names one dictionary
  ///  forever. A known ID with a different definition SHA256 is rejected,
  ///  never merged or rebound. docs/clg-contract.md section 2 defines allocation and hashing.
  public var GRAPH_ID: String! { let o = _accessor.offset(VT.GRAPH_ID); return _accessor.string(at: o) }
  public var GRAPH_IDSegmentArray: [UInt8]! { return _accessor.getVector(at: VT.GRAPH_ID) }
  public var PAYLOAD: clgPayloadClass { let o = _accessor.offset(VT.PAYLOAD); return o == 0 ? .unspecified : clgPayloadClass(rawValue: _accessor.readBuffer(of: UInt8.self, at: o)) ?? .unspecified }
  public var DEFINITION: CLGDefinition? { let o = _accessor.offset(VT.DEFINITION); return o == 0 ? nil : CLGDefinition(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public var STATE_BLOCK: CLGStateBlock? { let o = _accessor.offset(VT.STATE_BLOCK); return o == 0 ? nil : CLGStateBlock(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public var RESULT: CLGResult? { let o = _accessor.offset(VT.RESULT); return o == 0 ? nil : CLGResult(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  Value presence: false means omitted; true precedes value validation.
  public var HAS_PAYLOAD: Bool { let o = _accessor.offset(VT.HAS_PAYLOAD); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  public static func startCLG(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 6) }
  public static func add(GRAPH_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: GRAPH_ID, at: VT.GRAPH_ID) }
  public static func add(PAYLOAD: clgPayloadClass, _ fbb: inout FlatBufferBuilder) { fbb.add(element: PAYLOAD.rawValue, def: 0, at: VT.PAYLOAD) }
  public static func add(DEFINITION: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: DEFINITION, at: VT.DEFINITION) }
  public static func add(STATE_BLOCK: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: STATE_BLOCK, at: VT.STATE_BLOCK) }
  public static func add(RESULT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RESULT, at: VT.RESULT) }
  public static func add(HAS_PAYLOAD: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: HAS_PAYLOAD, def: false,
   at: VT.HAS_PAYLOAD) }
  public static func endCLG(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [4]); return end }
  public static func createCLG(
    _ fbb: inout FlatBufferBuilder,
    GRAPH_IDOffset GRAPH_ID: Offset,
    PAYLOAD: clgPayloadClass = .unspecified,
    DEFINITIONOffset DEFINITION: Offset = Offset(),
    STATE_BLOCKOffset STATE_BLOCK: Offset = Offset(),
    RESULTOffset RESULT: Offset = Offset(),
    HAS_PAYLOAD: Bool = false
  ) -> Offset {
    let __start = CLG.startCLG(&fbb)
    CLG.add(GRAPH_ID: GRAPH_ID, &fbb)
    CLG.add(PAYLOAD: PAYLOAD, &fbb)
    CLG.add(DEFINITION: DEFINITION, &fbb)
    CLG.add(STATE_BLOCK: STATE_BLOCK, &fbb)
    CLG.add(RESULT: RESULT, &fbb)
    CLG.add(HAS_PAYLOAD: HAS_PAYLOAD, &fbb)
    return CLG.endCLG(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.GRAPH_ID, fieldName: "GRAPH_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PAYLOAD, fieldName: "PAYLOAD", required: false, type: clgPayloadClass.self)
    try _v.visit(field: VT.DEFINITION, fieldName: "DEFINITION", required: false, type: ForwardOffset<CLGDefinition>.self)
    try _v.visit(field: VT.STATE_BLOCK, fieldName: "STATE_BLOCK", required: false, type: ForwardOffset<CLGStateBlock>.self)
    try _v.visit(field: VT.RESULT, fieldName: "RESULT", required: false, type: ForwardOffset<CLGResult>.self)
    try _v.visit(field: VT.HAS_PAYLOAD, fieldName: "HAS_PAYLOAD", required: false, type: Bool.self)
    _v.finish()
  }
}
